"use client"

import * as React from "react"

import { resolveCsvDialect, type CsvDialect, type CsvTable } from "@/lib/csv"
import { cn } from "@/lib/utils"

import { defaultCsvDownloadName, downloadCsvTable } from "./csv-viewer-download"
import { CsvGrid, type CsvGridHandle } from "./csv-viewer-grid"
import {
  getCsvErrorMessage,
  useCsvResourceState,
  type CsvCellAddress,
} from "./csv-viewer-state"
import { CsvViewerToolbar, useCsvViewerZoom } from "./csv-viewer-toolbar"

const BASE_FONT_SIZE = 13

export interface CsvScrollOptions {
  behavior?: ScrollBehavior
}

export interface CsvViewerHandle {
  scrollToCell: (
    cellAddress: CsvCellAddress,
    options?: CsvScrollOptions
  ) => void
  getViewportElement: () => HTMLDivElement | null
}

export interface CsvViewerProps {
  src?: string
  value?: string
  source?: Blob
  data?: CsvTable
  dialect?: CsvDialect
  className?: string
  toolbar?: boolean
  downloadName?: string
  height?: number
  fillHeight?: boolean
  activeCell?: CsvCellAddress | null
  isolateStyles?: boolean
}

export const CsvViewer = React.forwardRef<CsvViewerHandle, CsvViewerProps>(
  function CsvViewer(
    {
      src,
      value,
      data,
      source,
      dialect: dialectProp,
      className,
      toolbar = true,
      downloadName,
      height = 480,
      fillHeight = false,
      activeCell,
      isolateStyles = false,
    },
    ref
  ) {
    const dialect = React.useMemo(
      () =>
        resolveCsvDialect({
          dialect: dialectProp,
          descriptor: { src, fileName: downloadName },
        }),
      [dialectProp, downloadName, src]
    )
    const resourceState = useCsvResourceState({
      src,
      value,
      source,
      data,
      dialect,
    })
    const gridRef = React.useRef<CsvGridHandle>(null)
    const { zoom, setZoom } = useCsvViewerZoom()
    const columns = resourceState.columns
    const sourceRows = resourceState.sourceRows
    const resolvedDownloadName = downloadName ?? defaultCsvDownloadName(dialect)

    React.useImperativeHandle(
      ref,
      () => ({
        scrollToCell: (cellAddress, options) => {
          gridRef.current?.scrollToCell(cellAddress, options)
        },
        getViewportElement: () => gridRef.current?.getViewportElement() ?? null,
      }),
      []
    )

    const handleDownload = React.useCallback(() => {
      void downloadCsvTable({
        src,
        columns,
        sourceRows,
        dialect,
        downloadName: resolvedDownloadName,
      })
    }, [columns, dialect, resolvedDownloadName, sourceRows, src])

    const statusNode = React.useMemo(() => {
      if (resourceState.status === "error") {
        return (
          <div
            role="status"
            aria-live="polite"
            className="flex h-24 items-center justify-center px-3 text-center text-xs text-muted-foreground"
          >
            {getCsvErrorMessage(resourceState.error)}
          </div>
        )
      }
      if (sourceRows.length === 0 && resourceState.status !== "loading") {
        return (
          <div className="flex h-24 items-center justify-center text-xs text-muted-foreground">
            No rows
          </div>
        )
      }
      return null
    }, [resourceState, sourceRows.length])

    return (
      <div
        data-slot="csv-viewer"
        className={cn(
          "flex flex-col overflow-hidden rounded-xl border bg-card",
          fillHeight && "h-full min-h-0 flex-1",
          className
        )}
        style={{ fontSize: BASE_FONT_SIZE * zoom }}
      >
        {toolbar ? (
          <CsvViewerToolbar
            rowCount={sourceRows.length}
            columnCount={columns.length}
            isLoading={resourceState.status === "loading"}
            zoom={zoom}
            onZoomChange={setZoom}
            onDownload={handleDownload}
          />
        ) : null}
        <CsvGrid
          ref={gridRef}
          columns={columns}
          sourceRows={sourceRows}
          activeCell={activeCell ?? null}
          height={height}
          fillHeight={fillHeight}
          isolateStyles={isolateStyles}
          scale={zoom}
          statusNode={statusNode}
        />
      </div>
    )
  }
)

export { type CsvCellAddress, type CsvDialect, type CsvTable }

import { isTabDelimited, type CsvDialect } from "@/lib/csv"

export function escapeDelimitedField(value: string, delimiter: string): string {
  const text = value ?? ""
  return text.includes(delimiter) || /["\r\n]/.test(text)
    ? `"${text.replace(/"/g, '""')}"`
    : text
}

export function serializeCsvTable({
  columns,
  sourceRows,
  dialect,
}: {
  columns: string[]
  sourceRows: string[][]
  dialect: CsvDialect
}): string {
  const lines = [
    columns
      .map((value) => escapeDelimitedField(value, dialect.delimiter))
      .join(dialect.delimiter),
  ]
  for (const sourceRow of sourceRows) {
    lines.push(
      sourceRow
        .map((value) => escapeDelimitedField(value, dialect.delimiter))
        .join(dialect.delimiter)
    )
  }
  return lines.join("\r\n")
}

export function defaultCsvDownloadName(dialect: CsvDialect): string {
  return isTabDelimited(dialect) ? "data.tsv" : "data.csv"
}

export async function downloadCsvTable({
  src,
  columns,
  sourceRows,
  dialect,
  downloadName,
}: {
  src?: string
  columns: string[]
  sourceRows: string[][]
  dialect: CsvDialect
  downloadName: string
}): Promise<void> {
  const blob = src
    ? await fetch(src).then((response) => {
        if (!response.ok) {
          throw new Error(`Failed to load file: ${response.status}`)
        }
        return response.blob()
      })
    : new Blob([serializeCsvTable({ columns, sourceRows, dialect })], {
        type: isTabDelimited(dialect)
          ? "text/tab-separated-values;charset=utf-8"
          : "text/csv;charset=utf-8",
      })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement("a")
  anchor.href = url
  anchor.download = downloadName
  anchor.rel = "noreferrer"
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  URL.revokeObjectURL(url)
}

"use client"

import * as React from "react"
import { ChevronDown, ChevronUp } from "lucide-react"

import { cn } from "@/lib/utils"

import { CSV_SCROLLBAR_CSS, HeaderAwareScrollbar } from "./csv-viewer-scrollbar"
import type { CsvCellAddress } from "./csv-viewer-state"
import { CsvStyleScope } from "./csv-viewer-style-scope"
import { fixedGridColumnWidths } from "./fixed-grid-columns"
import {
  getFixedGridCanvasStyle,
  getFixedGridRowWindowStyle,
} from "./fixed-grid-layout"
import { getFixedGridRowStyle } from "./fixed-grid-row-style"
import { buildVirtualGridTemplate } from "./fixed-grid-template"
import { FixedGridViewport } from "./fixed-grid-viewport"
import {
  useFixedGridVirtualization,
  type FixedGridColumnItem,
} from "./fixed-grid-virtualization"

type Row = string[]

export interface CsvGridHandle {
  scrollToCell: (
    cellAddress: CsvCellAddress,
    options?: { behavior?: ScrollBehavior }
  ) => void
  getViewportElement: () => HTMLDivElement | null
}

export interface CsvGridProps {
  columns: string[]
  sourceRows: string[][]
  activeCell: CsvCellAddress | null
  height: number
  fillHeight: boolean
  isolateStyles: boolean
  scale: number
  statusNode: React.ReactNode
}

const CSV_TABLE_LABEL = "CSV data"
const COLUMN_WIDTH = 180
const COLUMN_OVERSCAN = 2
const JUMP_COLUMN_OVERSCAN = 0
const ROW_HEIGHT = 33
const ROW_NUMBER_WIDTH = 56
const ROW_OVERSCAN = 4
const JUMP_ROW_OVERSCAN = 0
const SMALL_TABLE_ROW_LIMIT = 200
const SMALL_TABLE_COLUMN_LIMIT = 8

export const CsvGrid = React.forwardRef<CsvGridHandle, CsvGridProps>(
  function CsvGrid(
    {
      columns,
      sourceRows,
      activeCell,
      height,
      fillHeight,
      isolateStyles,
      scale,
      statusNode,
    },
    ref
  ) {
    const [sort, setSort] = React.useState<{
      columnIndex: number
      descending: boolean
    } | null>(null)

    const toggleSort = React.useCallback((columnIndex: number) => {
      setSort((current) =>
        !current || current.columnIndex !== columnIndex
          ? { columnIndex, descending: false }
          : current.descending
            ? null
            : { columnIndex, descending: true }
      )
    }, [])

    const rowOrder = React.useMemo<number[] | null>(() => {
      if (!sort) return null
      const order = sourceRows.map((_, rowIndex) => rowIndex)
      const { columnIndex } = sort
      order.sort((a, b) =>
        compareCells(
          sourceRows[a][columnIndex] ?? "",
          sourceRows[b][columnIndex] ?? ""
        )
      )
      if (sort.descending) order.reverse()
      return order
    }, [sourceRows, sort])

    const displayIndexByRowIndex = React.useMemo<Map<
      number,
      number
    > | null>(() => {
      if (!rowOrder) return null
      const map = new Map<number, number>()
      rowOrder.forEach((rowIndex, displayRowIndex) => {
        map.set(rowIndex, displayRowIndex)
      })
      return map
    }, [rowOrder])

    const rowAt = React.useCallback(
      (displayRowIndex: number): Row =>
        sourceRows[rowOrder ? rowOrder[displayRowIndex] : displayRowIndex],
      [sourceRows, rowOrder]
    )

    const rowIndexAt = React.useCallback(
      (displayRowIndex: number): number =>
        rowOrder ? rowOrder[displayRowIndex] : displayRowIndex,
      [rowOrder]
    )

    const viewportRef = React.useRef<HTMLDivElement>(null)
    const [viewportElement, setViewportElement] =
      React.useState<HTMLDivElement | null>(null)
    const setViewportRef = React.useCallback((node: HTMLDivElement | null) => {
      viewportRef.current = node
      setViewportElement((current) => (current === node ? current : node))
    }, [])
    const columnCount = columns.length
    const columnOffset = 1
    const shouldVirtualizeRows = sourceRows.length > SMALL_TABLE_ROW_LIMIT
    const shouldVirtualizeColumns = columnCount > SMALL_TABLE_COLUMN_LIMIT
    const effectiveRowHeight = Math.max(1, Math.round(ROW_HEIGHT * scale))
    const effectiveColumnWidth = Math.max(1, Math.round(COLUMN_WIDTH * scale))
    const effectiveRowNumberWidth = Math.round(ROW_NUMBER_WIDTH * scale)

    const {
      virtualRows,
      totalRowSize,
      totalColumnSize,
      columnItems,
      leftPad,
      rightPad,
      scrollToCell,
    } = useFixedGridVirtualization({
      rowCount: sourceRows.length,
      columnCount,
      rowSize: effectiveRowHeight,
      columnSize: effectiveColumnWidth,
      rowOverscan: ROW_OVERSCAN,
      columnOverscan: COLUMN_OVERSCAN,
      jumpRowOverscan: JUMP_ROW_OVERSCAN,
      jumpColumnOverscan: JUMP_COLUMN_OVERSCAN,
      scrollRef: viewportRef,
      scrollElement: viewportElement,
      virtualizeColumns: shouldVirtualizeColumns,
    })

    React.useImperativeHandle(
      ref,
      () => ({
        scrollToCell: (cellAddress, options) => {
          const behavior = options?.behavior ?? "smooth"
          const displayRowIndex =
            displayIndexByRowIndex?.get(cellAddress.rowIndex) ??
            cellAddress.rowIndex
          scrollToCell({
            rowIndex: displayRowIndex,
            columnIndex: cellAddress.columnIndex,
            behavior,
            align: "center",
          })
        },
        getViewportElement: () => viewportRef.current,
      }),
      [displayIndexByRowIndex, scrollToCell]
    )

    const gridTemplate = React.useMemo(
      () =>
        buildVirtualGridTemplate({
          leadingWidth: effectiveRowNumberWidth,
          leftPad,
          columnWidths: fixedGridColumnWidths(columnItems),
          rightPad,
        }),
      [effectiveRowNumberWidth, leftPad, columnItems, rightPad]
    )
    const totalWidth = effectiveRowNumberWidth + totalColumnSize

    return (
      <div
        data-slot="csv-grid"
        role="table"
        aria-label={CSV_TABLE_LABEL}
        aria-rowcount={sourceRows.length + 1}
        aria-colcount={columnCount + columnOffset}
        className={cn("relative", fillHeight && "min-h-0 flex-1")}
      >
        <CsvStyleScope
          isolate={isolateStyles}
          className={cn("relative", fillHeight && "h-full min-h-0")}
          style={fillHeight ? undefined : { height, maxHeight: "100%" }}
        >
          <style>{CSV_SCROLLBAR_CSS}</style>
          <FixedGridViewport scrollRef={setViewportRef} dataSlot="csv-body">
            <div
              style={getFixedGridCanvasStyle({
                width: totalWidth,
                contain: true,
              })}
            >
              <div
                role="row"
                aria-rowindex={1}
                data-slot="csv-header"
                className="sticky top-0 z-20 grid border-b"
                style={{
                  gridTemplateColumns: gridTemplate,
                  backgroundColor:
                    "color-mix(in oklab, var(--card) 92%, var(--foreground))",
                }}
              >
                <div
                  role="columnheader"
                  aria-colindex={1}
                  aria-label="Row number"
                  className="sticky left-0 z-10 border-r bg-[color-mix(in_oklab,var(--card)_94%,var(--foreground))]"
                  style={{ height: effectiveRowHeight }}
                />
                <Spacer width={leftPad} />
                {columnItems.map((item) => (
                  <HeaderCell
                    key={item.index}
                    name={columns[item.index] || `Column ${item.index + 1}`}
                    columnIndex={columnOffset + item.index + 1}
                    height={effectiveRowHeight}
                    sorted={
                      sort?.columnIndex === item.index
                        ? sort.descending
                          ? "desc"
                          : "asc"
                        : false
                    }
                    onToggle={() => toggleSort(item.index)}
                  />
                ))}
                <Spacer width={rightPad} />
              </div>

              {statusNode ? (
                statusNode
              ) : shouldVirtualizeRows ? (
                <div
                  role="rowgroup"
                  style={getFixedGridRowWindowStyle({ height: totalRowSize })}
                >
                  {virtualRows.map((virtualRow) => (
                    <CsvRow
                      key={virtualRow.index}
                      cells={rowAt(virtualRow.index)}
                      displayRowIndex={virtualRow.index}
                      rowIndex={rowIndexAt(virtualRow.index)}
                      gridTemplate={gridTemplate}
                      rowHeight={effectiveRowHeight}
                      columnOffset={columnOffset}
                      columnItems={columnItems}
                      leftPad={leftPad}
                      rightPad={rightPad}
                      start={virtualRow.start}
                      activeColumnIndex={
                        activeCell?.rowIndex === rowIndexAt(virtualRow.index)
                          ? activeCell.columnIndex
                          : null
                      }
                    />
                  ))}
                </div>
              ) : (
                <div role="rowgroup">
                  {sourceRows.map((_, displayRowIndex) => (
                    <CsvRow
                      key={displayRowIndex}
                      cells={rowAt(displayRowIndex)}
                      displayRowIndex={displayRowIndex}
                      rowIndex={rowIndexAt(displayRowIndex)}
                      gridTemplate={gridTemplate}
                      rowHeight={effectiveRowHeight}
                      columnOffset={columnOffset}
                      columnItems={columnItems}
                      leftPad={leftPad}
                      rightPad={rightPad}
                      activeColumnIndex={
                        activeCell?.rowIndex === rowIndexAt(displayRowIndex)
                          ? activeCell.columnIndex
                          : null
                      }
                    />
                  ))}
                </div>
              )}
            </div>
          </FixedGridViewport>
          <HeaderAwareScrollbar
            scrollRef={viewportRef}
            headerHeight={effectiveRowHeight}
          />
        </CsvStyleScope>
      </div>
    )
  }
)

function Spacer({ width }: { width: number }) {
  return <div role="presentation" aria-hidden style={{ width }} />
}

function HeaderCell({
  name,
  columnIndex,
  height,
  sorted,
  onToggle,
}: {
  name: string
  columnIndex: number
  height: number
  sorted: "asc" | "desc" | false
  onToggle: () => void
}) {
  return (
    <div
      role="columnheader"
      aria-colindex={columnIndex}
      aria-sort={
        sorted === "asc"
          ? "ascending"
          : sorted === "desc"
            ? "descending"
            : "none"
      }
      data-slot="csv-header-cell"
      className="border-r last:border-r-0"
    >
      <button
        type="button"
        onClick={onToggle}
        className="flex w-full items-center gap-1 px-3 text-left font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:bg-muted focus-visible:outline-none"
        style={{ height }}
        title={`Sort by ${name}`}
      >
        <span className="truncate">{name}</span>
        {sorted ? (
          sorted === "asc" ? (
            <ChevronUp
              className="size-3.5 shrink-0 text-muted-foreground"
              aria-hidden
            />
          ) : (
            <ChevronDown
              className="size-3.5 shrink-0 text-muted-foreground"
              aria-hidden
            />
          )
        ) : null}
      </button>
    </div>
  )
}

function compareCells(a: string, b: string): number {
  const left = Number(a)
  const right = Number(b)
  if (a !== "" && b !== "" && !Number.isNaN(left) && !Number.isNaN(right)) {
    return left - right
  }
  return a < b ? -1 : a > b ? 1 : 0
}

const CsvRow = React.memo(function CsvRow({
  cells,
  displayRowIndex,
  rowIndex,
  gridTemplate,
  rowHeight,
  columnOffset,
  columnItems,
  leftPad,
  rightPad,
  start,
  activeColumnIndex,
}: {
  cells: Row | undefined
  displayRowIndex: number
  rowIndex: number
  gridTemplate: string
  rowHeight: number
  columnOffset: number
  columnItems: FixedGridColumnItem[]
  leftPad: number
  rightPad: number
  start?: number
  activeColumnIndex?: number | null
}) {
  const isVirtualized = start !== undefined
  const style: React.CSSProperties = !isVirtualized
    ? { gridTemplateColumns: gridTemplate, height: rowHeight }
    : getFixedGridRowStyle({
        gridTemplate,
        rowHeight,
        top: start,
      })
  return (
    <div
      role="row"
      aria-rowindex={displayRowIndex + 2}
      data-slot="csv-row"
      className={cn(
        "grid border-b",
        !isVirtualized && "group hover:bg-muted/40"
      )}
      style={style}
    >
      <div
        role="rowheader"
        aria-colindex={1}
        data-slot="csv-row-number"
        className={cn(
          "sticky left-0 z-[1] flex items-center justify-end border-r bg-card px-2 text-muted-foreground tabular-nums",
          !isVirtualized &&
            "group-hover:bg-[color-mix(in_oklab,var(--card)_97%,var(--foreground))]"
        )}
      >
        {rowIndex + 1}
      </div>
      <Spacer width={leftPad} />
      {columnItems.map((item) => {
        const text = cells?.[item.index] ?? ""
        const isActive = activeColumnIndex === item.index
        return (
          <div
            key={item.index}
            role="cell"
            aria-colindex={columnOffset + item.index + 1}
            data-slot="csv-cell"
            className={cn(
              "flex items-center truncate border-r px-3 last:border-r-0",
              isActive &&
                "bg-primary/12 ring-1 ring-primary/50 ring-offset-0 ring-inset"
            )}
            title={isVirtualized ? undefined : text}
          >
            <span className="truncate">{text}</span>
          </div>
        )
      })}
      <Spacer width={rightPad} />
    </div>
  )
})

"use client"

import * as React from "react"

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

const MINIMUM_ROW_WINDOW = 32
const INITIAL_COLUMN_WINDOW = 8

export interface FixedGridColumnItem {
  index: number
  widthPx: number
}

export interface FixedGridVirtualItem {
  index: number
  start: number
  size: number
  end: number
}

export interface FixedGridScrollTarget {
  rowIndex: number
  columnIndex: number
  align?: "start" | "center" | "end" | "auto"
  behavior?: ScrollBehavior
}

export interface FixedRowScrollTarget {
  rowIndex: number
  align?: "start" | "center" | "end" | "auto"
  behavior?: ScrollBehavior
}

export function useFixedGridVirtualization({
  rowCount,
  columnCount,
  rowSize,
  columnSize,
  rowOverscan,
  columnOverscan,
  jumpRowOverscan = rowOverscan,
  jumpColumnOverscan = columnOverscan,
  scrollRef,
  scrollElement,
  virtualizeColumns = true,
}: {
  rowCount: number
  columnCount: number
  rowSize: number
  columnSize: number
  rowOverscan: number
  columnOverscan: number
  jumpRowOverscan?: number
  jumpColumnOverscan?: number
  scrollRef: React.RefObject<HTMLElement | null>
  scrollElement?: HTMLElement | null
  virtualizeColumns?: boolean
}) {
  const viewport = useFixedGridViewport(scrollElement ?? scrollRef.current)

  const totalRowSize = rowCount * rowSize
  const totalColumnSize = columnCount * columnSize
  const activeRowOverscan = viewport.isJumpingRows
    ? jumpRowOverscan
    : rowOverscan
  const activeColumnOverscan =
    viewport.isJumpingColumns || viewport.isJumpingRows
      ? jumpColumnOverscan
      : columnOverscan

  const virtualRows = React.useMemo(
    () =>
      fixedVirtualItems({
        count: rowCount,
        size: rowSize,
        scrollOffset: viewport.scrollTop,
        viewportSize: viewport.clientHeight,
        overscan: activeRowOverscan,
        minimumVisibleCount: MINIMUM_ROW_WINDOW,
      }),
    [
      rowCount,
      rowSize,
      viewport.scrollTop,
      viewport.clientHeight,
      activeRowOverscan,
    ]
  )

  const columnWindow = React.useMemo<{
    columnItems: FixedGridColumnItem[]
    leftPad: number
    rightPad: number
  }>(() => {
    if (!virtualizeColumns) {
      return {
        columnItems: Array.from({ length: columnCount }, (_, index) => ({
          index,
          widthPx: columnSize,
        })),
        leftPad: 0,
        rightPad: 0,
      }
    }

    const virtualColumns = fixedVirtualItems({
      count: columnCount,
      size: columnSize,
      scrollOffset: viewport.scrollLeft,
      viewportSize: viewport.clientWidth,
      overscan: activeColumnOverscan,
      minimumVisibleCount: INITIAL_COLUMN_WINDOW,
    })

    return {
      columnItems: virtualColumns.map((item) => ({
        index: item.index,
        widthPx: item.size,
      })),
      leftPad: virtualColumns.length ? virtualColumns[0].start : 0,
      rightPad: virtualColumns.length
        ? totalColumnSize - virtualColumns[virtualColumns.length - 1].end
        : 0,
    }
  }, [
    virtualizeColumns,
    columnCount,
    columnSize,
    viewport.scrollLeft,
    viewport.clientWidth,
    activeColumnOverscan,
    totalColumnSize,
  ])

  const scrollToCell = React.useCallback(
    ({
      rowIndex,
      columnIndex,
      align = "center",
      behavior = "smooth",
    }: FixedGridScrollTarget) => {
      const scrollElement = scrollRef.current
      if (!scrollElement) return
      scrollElement.scrollTo({
        top: fixedScrollOffset({
          index: rowIndex,
          itemSize: rowSize,
          viewportSize: scrollElement.clientHeight,
          align,
        }),
        left: fixedScrollOffset({
          index: columnIndex,
          itemSize: columnSize,
          viewportSize: scrollElement.clientWidth,
          align,
        }),
        behavior,
      })
    },
    [columnSize, rowSize, scrollRef]
  )

  return {
    virtualRows,
    totalRowSize,
    totalColumnSize,
    scrollToCell,
    ...columnWindow,
  }
}

export function useFixedRowVirtualization({
  rowCount,
  rowSize,
  rowOverscan,
  jumpRowOverscan = rowOverscan,
  scrollRef,
}: {
  rowCount: number
  rowSize: number
  rowOverscan: number
  jumpRowOverscan?: number
  scrollRef: React.RefObject<HTMLElement | null>
}) {
  const [range, setRange] = React.useState({ start: 0, end: 0 })
  const rangeRef = React.useRef(range)
  const rafRef = React.useRef(0)
  const totalRowSize = rowCount * rowSize

  const setMeasuredRange = React.useCallback((next: typeof range) => {
    const current = rangeRef.current
    if (current.start === next.start && current.end === next.end) return
    rangeRef.current = next
    setRange(next)
  }, [])

  const measure = React.useCallback(() => {
    const scrollElement = scrollRef.current
    if (!scrollElement || rowCount <= 0 || rowSize <= 0) {
      setMeasuredRange({ start: 0, end: 0 })
      return
    }

    const scrollTop = scrollElement.scrollTop
    const viewportHeight = scrollElement.clientHeight
    const firstVisibleRow = Math.floor(scrollTop / rowSize)
    const visibleRowCount = Math.ceil(viewportHeight / rowSize)
    const previous = rangeRef.current
    const isJumping =
      Math.abs(firstVisibleRow - previous.start) > visibleRowCount * 0.45
    const activeOverscan = isJumping ? jumpRowOverscan : rowOverscan
    const start = Math.max(0, firstVisibleRow - activeOverscan)
    const end = Math.min(
      rowCount,
      firstVisibleRow + visibleRowCount + activeOverscan
    )

    if (previous.end > rowCount || previous.start >= rowCount) {
      setMeasuredRange({ start, end })
      return
    }

    const bufferRows = Math.max(1, Math.floor(activeOverscan / 2))
    const visibleStart = firstVisibleRow
    const visibleEnd = Math.min(rowCount, firstVisibleRow + visibleRowCount)
    const hasBeforeBuffer =
      previous.start === 0 || visibleStart >= previous.start + bufferRows
    const hasAfterBuffer =
      previous.end === rowCount || visibleEnd <= previous.end - bufferRows

    if (hasBeforeBuffer && hasAfterBuffer) return
    setMeasuredRange({ start, end })
  }, [
    jumpRowOverscan,
    rowCount,
    rowOverscan,
    rowSize,
    scrollRef,
    setMeasuredRange,
  ])

  React.useLayoutEffect(() => {
    measure()
  }, [measure])

  React.useEffect(() => {
    const scrollElement = scrollRef.current
    if (!scrollElement) return

    const scheduleMeasure = () => {
      if (rafRef.current) return
      rafRef.current = requestAnimationFrame(() => {
        rafRef.current = 0
        measure()
      })
    }

    scrollElement.addEventListener("scroll", scheduleMeasure, {
      passive: true,
    })
    const observer = new ResizeObserver(scheduleMeasure)
    observer.observe(scrollElement)
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current)
      scrollElement.removeEventListener("scroll", scheduleMeasure)
      observer.disconnect()
    }
  }, [scrollRef, measure])

  const virtualRows = React.useMemo(
    () =>
      Array.from({ length: range.end - range.start }, (_, offset) => {
        const index = range.start + offset
        const start = index * rowSize
        return {
          index,
          start,
          size: rowSize,
          end: start + rowSize,
        }
      }),
    [range, rowSize]
  )

  const scrollToRow = React.useCallback(
    ({
      rowIndex,
      align = "center",
      behavior = "smooth",
    }: FixedRowScrollTarget) => {
      const scrollElement = scrollRef.current
      if (!scrollElement) return
      scrollElement.scrollTo({
        top: fixedScrollOffset({
          index: rowIndex,
          itemSize: rowSize,
          viewportSize: scrollElement.clientHeight,
          align,
        }),
        behavior,
      })
    },
    [rowSize, scrollRef]
  )

  return {
    virtualRows,
    totalRowSize,
    scrollToRow,
  }
}

interface FixedGridViewport {
  scrollTop: number
  scrollLeft: number
  clientHeight: number
  clientWidth: number
  isJumpingRows: boolean
  isJumpingColumns: boolean
}

interface FixedVirtualWindow {
  count: number
  size: number
  scrollOffset: number
  viewportSize: number
  overscan: number
  minimumVisibleCount?: number
}

function useFixedGridViewport(scrollElement: HTMLElement | null | undefined) {
  const [viewport, setViewport] = React.useState<FixedGridViewport>({
    scrollTop: 0,
    scrollLeft: 0,
    clientHeight: 0,
    clientWidth: 0,
    isJumpingRows: false,
    isJumpingColumns: false,
  })

  useIsomorphicLayoutEffect(() => {
    if (!scrollElement) return

    let frame = 0
    let lastScrollTop = scrollElement.scrollTop
    let lastScrollLeft = scrollElement.scrollLeft

    const readViewport = () => {
      frame = 0
      const scrollTop = scrollElement.scrollTop
      const scrollLeft = scrollElement.scrollLeft
      const clientHeight = scrollElement.clientHeight
      const clientWidth = scrollElement.clientWidth
      const rowDelta = Math.abs(scrollTop - lastScrollTop)
      const columnDelta = Math.abs(scrollLeft - lastScrollLeft)
      lastScrollTop = scrollTop
      lastScrollLeft = scrollLeft

      setViewport((current) => {
        const next: FixedGridViewport = {
          scrollTop,
          scrollLeft,
          clientHeight,
          clientWidth,
          isJumpingRows: rowDelta > clientHeight * 0.45,
          isJumpingColumns: columnDelta > clientWidth * 0.45,
        }
        return fixedGridViewportEqual(current, next) ? current : next
      })
    }

    const scheduleRead = () => {
      if (frame) return
      frame = requestAnimationFrame(readViewport)
    }

    readViewport()
    scrollElement.addEventListener("scroll", scheduleRead, { passive: true })
    const observer = new ResizeObserver(scheduleRead)
    observer.observe(scrollElement)

    return () => {
      if (frame) cancelAnimationFrame(frame)
      scrollElement.removeEventListener("scroll", scheduleRead)
      observer.disconnect()
    }
  }, [scrollElement])

  return viewport
}

export function fixedVirtualItems({
  count,
  size,
  scrollOffset,
  viewportSize,
  overscan,
  minimumVisibleCount = 1,
}: FixedVirtualWindow): FixedGridVirtualItem[] {
  if (count <= 0 || size <= 0) return []
  const effectiveViewportSize = Math.max(
    viewportSize,
    size * minimumVisibleCount
  )
  const visibleStart = Math.floor(scrollOffset / size)
  const visibleEnd = Math.ceil((scrollOffset + effectiveViewportSize) / size)
  const start = Math.max(0, visibleStart - overscan)
  const end = Math.min(count - 1, visibleEnd + overscan)
  return Array.from({ length: end - start + 1 }, (_, offset) => {
    const index = start + offset
    const itemStart = index * size
    return {
      index,
      start: itemStart,
      size,
      end: itemStart + size,
    }
  })
}

export function fixedScrollOffset({
  index,
  itemSize,
  viewportSize,
  align,
}: {
  index: number
  itemSize: number
  viewportSize: number
  align: NonNullable<FixedGridScrollTarget["align"]>
}) {
  const start = index * itemSize
  if (align === "end") return start - viewportSize + itemSize
  if (align === "center") return start - viewportSize / 2 + itemSize / 2
  return start
}

function fixedGridViewportEqual(
  left: FixedGridViewport,
  right: FixedGridViewport
) {
  return (
    left.scrollTop === right.scrollTop &&
    left.scrollLeft === right.scrollLeft &&
    left.clientHeight === right.clientHeight &&
    left.clientWidth === right.clientWidth &&
    left.isJumpingRows === right.isJumpingRows &&
    left.isJumpingColumns === right.isJumpingColumns
  )
}

